# Generated by scripts/prepare-homebrew.py from the local crate archive.
class Rightcommit < Formula
  desc "Self-hosted, Rust-built orchestration for Claude Code, Codex and Pi Agent"
  homepage "https://rightcommit.com"
  url "https://static.crates.io/crates/rightcommit/rightcommit-1.0.0.crate"
  version "1.0.0"
  sha256 "65770810dde78290d5553aed844826ed7f2e0359df12f1ccac7fa4082f4d3850"
  license "FSL-1.1-ALv2"

  depends_on "cmake" => :build
  depends_on "pkgconf" => :build
  depends_on "protobuf" => :build
  depends_on "rust"
  depends_on "node@22"
  depends_on "openssl@3"
  depends_on "git"
  depends_on "python@3.14"
  depends_on "ripgrep"

  def install
    system "cargo", "install", "--locked", *std_cargo_args(path: ".", root: libexec)
    (bin/"rightcommit").write <<~SH
      #!/bin/bash
      export PATH="#{Formula["node@22"].opt_bin}:#{Formula["rust"].opt_bin}:$PATH"
      exec "#{libexec}/bin/rightcommit" "$@"
    SH
    chmod 0755, bin/"rightcommit"
  end

  def caveats
    <<~EOS
      Start from a writable directory:
        mkdir -p ~/rightcommit && cd ~/rightcommit
        rightcommit setup
        rightcommit
      Open http://localhost:8080. Data stays in ./data.
      Run setup again after upgrading to refresh Pi extensions.
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/rightcommit --version")
    port = free_port
    pid = spawn({"NODO_LISTEN" => "127.0.0.1:#{port}"}, bin/"rightcommit")
    begin
      system "curl", "--fail", "--retry", "15", "--retry-connrefused",
        "--retry-delay", "1", "http://127.0.0.1:#{port}/healthz"
      assert_path_exists testpath/"data/system/assets"
    ensure
      Process.kill("INT", pid)
      Process.wait(pid)
    end
  end
end
